-- Auto-generated by wow-classic-converter. Loaded first by the TOC.
--
-- Provides addon-private versions of modern (retail) APIs, built on the
-- older APIs that WoW Classic clients still expose. Nothing here touches
-- real globals except the single table __SHIM__, so other addons are not
-- affected. Every fill is used only when the real client lacks that API,
-- so the converted addon keeps working on retail too.

local S = {}
_G["__SHIM__"] = S

local _G = _G
local type, select, pairs, ipairs, pcall, setmetatable, rawget, tostring =
      type, select, pairs, ipairs, pcall, setmetatable, rawget, tostring

-- Wraps namespace `name`: real functions win, `fills` cover the gaps.
local function namespace(name, fills)
	local t = {}
	for k, fn in pairs(fills) do
		local real = _G[name]
		if not (type(real) == "table" and real[k] ~= nil) then
			t[k] = fn
		end
	end
	setmetatable(t, { __index = function(_, k)
		local real = _G[name]
		if type(real) == "table" then return real[k] end
	end })
	S[name] = t
end

-- Exposes `name` as the real global when present, otherwise the fill.
local function global(name, fill)
	local real = _G[name]
	if real ~= nil then S[name] = real else S[name] = fill end
end

local function call(name, ...)
	local fn = _G[name]
	if type(fn) == "function" then return fn(...) end
end

local function truthy(v) return v == true or (v ~= nil and v ~= false and v ~= 0) end

---------------------------------------------------------------------------
-- Events: modern clients raise an error when an addon registers an event
-- the client doesn't know. Retail-only events are skipped instead.
---------------------------------------------------------------------------
local validEvents = {}
local probe
local function isValidEvent(event)
	if type(event) ~= "string" then return true end
	local cached = validEvents[event]
	if cached ~= nil then return cached end
	local ok
	local EU = _G.C_EventUtils
	if EU and EU.IsEventValid then
		ok = EU.IsEventValid(event) and true or false
	else
		probe = probe or _G.CreateFrame("Frame")
		ok = pcall(probe.RegisterEvent, probe, event)
		if ok then probe:UnregisterEvent(event) end
	end
	validEvents[event] = ok
	return ok
end
S.IsEventValid = isValidEvent

function S.RegisterEvent(obj, event, ...)
	if not isValidEvent(event) then return false end
	return obj:RegisterEvent(event, ...)
end

function S.RegisterUnitEvent(obj, event, ...)
	if not isValidEvent(event) then return false end
	if obj.RegisterUnitEvent then return obj:RegisterUnitEvent(event, ...) end
	return obj:RegisterEvent(event)
end

function S.UnregisterEvent(obj, event, ...)
	if not isValidEvent(event) then return false end
	return obj:UnregisterEvent(event, ...)
end

