-- C_Spell (retail 11.0 moved spell globals here and returns tables)
---------------------------------------------------------------------------
local function spellName(spell)
	if type(spell) == "number" then return (call("GetSpellInfo", spell)) end
	return spell
end

namespace("C_Spell", {
	GetSpellInfo = function(spell)
		if spell == nil then return nil end
		local name, _, icon, castTime, minRange, maxRange, spellID, originalIcon = call("GetSpellInfo", spell)
		if not name then return nil end
		return {
			name = name, iconID = icon, originalIconID = originalIcon or icon,
			castTime = castTime, minRange = minRange, maxRange = maxRange, spellID = spellID,
		}
	end,
	GetSpellName = function(spell) return (call("GetSpellInfo", spell)) end,
	GetSpellTexture = function(spell)
		local tex = call("GetSpellTexture", spell)
		return tex, tex
	end,
	GetSpellLink = function(...) return call("GetSpellLink", ...) end,
	GetSpellDescription = function(...) return call("GetSpellDescription", ...) end,
	GetSpellSubtext = function(...) return call("GetSpellSubtext", ...) end,
	GetSpellPowerCost = function(...) return call("GetSpellPowerCost", ...) end,
	GetSpellCooldown = function(spell)
		local start, duration, enabled, modRate = call("GetSpellCooldown", spell)
		if not start then return nil end
		return { startTime = start, duration = duration, isEnabled = truthy(enabled), modRate = modRate or 1 }
	end,
	GetSpellCharges = function(spell)
		local cur, max, start, duration, modRate = call("GetSpellCharges", spell)
		if not cur then return nil end
		return {
			currentCharges = cur, maxCharges = max, cooldownStartTime = start,
			cooldownDuration = duration, chargeModRate = modRate or 1,
		}
	end,
	GetSpellCastCount = function(...) return call("GetSpellCount", ...) or 0 end,
	IsSpellUsable = function(...) return call("IsUsableSpell", ...) end,
	IsSpellInRange = function(spell, unit)
		local r = call("IsSpellInRange", spellName(spell), unit)
		if r == nil then return nil end
		return truthy(r)
	end,
	IsCurrentSpell = function(...) return truthy(call("IsCurrentSpell", ...)) end,
	IsAutoRepeatSpell = function(...) return truthy(call("IsAutoRepeatSpell", ...)) end,
	DoesSpellExist = function(spell)
		if _G.DoesSpellExist then return _G.DoesSpellExist(spell) end
		return call("GetSpellInfo", spell) ~= nil
	end,
	GetOverrideSpell = function(spell) return spell end,
	PickupSpell = function(...) return call("PickupSpell", ...) end,
})

