---------------------------------------------------------------------------
-- C_UnitAuras (retail returns AuraData tables)
---------------------------------------------------------------------------
local function auraData(filter, name, icon, count, dispelType, duration, expirationTime, source,
		isStealable, showPersonal, spellId, canApplyAura, isBossDebuff, castByPlayer, showAll, timeMod, ...)
	if not name then return nil end
	filter = filter or ""
	local harmful = filter:find("HARMFUL") ~= nil
	return {
		name = name, icon = icon, applications = count or 0, dispelName = dispelType,
		duration = duration or 0, expirationTime = expirationTime or 0, sourceUnit = source,
		isStealable = truthy(isStealable), nameplateShowPersonal = truthy(showPersonal),
		spellId = spellId, canApplyAura = truthy(canApplyAura), isBossAura = truthy(isBossDebuff),
		isFromPlayerOrPlayerPet = truthy(castByPlayer), nameplateShowAll = truthy(showAll),
		timeMod = timeMod or 1, points = { ... }, isHarmful = harmful, isHelpful = not harmful,
		charges = 1, maxCharges = 1,
	}
end

local function withBase(base, filter)
	if filter and filter ~= "" then return base .. "|" .. filter end
	return base
end

local function findAura(unit, filter, match)
	for i = 1, 255 do
		local data = auraData(filter, call("UnitAura", unit, i, filter))
		if not data then return nil end
		if match(data) then return data end
	end
end

namespace("C_UnitAuras", {
	GetAuraDataByIndex = function(unit, index, filter)
		return auraData(filter, call("UnitAura", unit, index, filter))
	end,
	GetBuffDataByIndex = function(unit, index, filter)
		local f = withBase("HELPFUL", filter)
		return auraData(f, call("UnitAura", unit, index, f))
	end,
	GetDebuffDataByIndex = function(unit, index, filter)
		local f = withBase("HARMFUL", filter)
		return auraData(f, call("UnitAura", unit, index, f))
	end,
	GetPlayerAuraBySpellID = function(spellID)
		local m = function(d) return d.spellId == spellID end
		return findAura("player", "HELPFUL", m) or findAura("player", "HARMFUL", m)
	end,
	GetAuraDataBySpellName = function(unit, name, filter)
		local m = function(d) return d.name == name end
		if filter and filter ~= "" then return findAura(unit, filter, m) end
		return findAura(unit, "HELPFUL", m) or findAura(unit, "HARMFUL", m)
	end,
})

