-- C_QuestLog
---------------------------------------------------------------------------
local function questIndexFor(questID)
	local n = call("GetNumQuestLogEntries") or 0
	for i = 1, n do
		if select(8, call("GetQuestLogTitle", i)) == questID then return i end
	end
end

namespace("C_QuestLog", {
	GetNumQuestLogEntries = function() return call("GetNumQuestLogEntries") end,
	GetInfo = function(index)
		local title, level, suggestedGroup, isHeader, isCollapsed, isComplete, frequency, questID = call("GetQuestLogTitle", index)
		if not title then return nil end
		return {
			title = title, level = level, suggestedGroup = suggestedGroup, isHeader = truthy(isHeader),
			isCollapsed = truthy(isCollapsed), frequency = frequency, questID = questID,
			questLogIndex = index, isOnMap = false, isHidden = false,
			-- Kept for convenience: classic's completion flag (1 = done, -1 = failed).
			isComplete = isComplete,
		}
	end,
	GetLogIndexForQuestID = questIndexFor,
	IsOnQuest = function(questID) return questIndexFor(questID) ~= nil end,
	GetTitleForQuestID = function(questID)
		local i = questIndexFor(questID)
		if i then return (call("GetQuestLogTitle", i)) end
	end,
	IsQuestFlaggedCompleted = function(questID)
		return truthy(call("IsQuestFlaggedCompleted", questID))
	end,
	IsComplete = function(questID)
		local i = questIndexFor(questID)
		return i ~= nil and select(6, call("GetQuestLogTitle", i)) == 1
	end,
})

