---------------------------------------------------------------------------
-- Settings (retail options panel) -> Interface Options
---------------------------------------------------------------------------
do
	local categories = {}
	local function makeCategory(frame, name)
		local cat = { ID = name, name = name, frame = frame }
		function cat:GetID() return self.ID end
		function cat:GetName() return self.name end
		categories[name] = cat
		return cat
	end
	namespace("Settings", {
		RegisterCanvasLayoutCategory = function(frame, name)
			frame.name = name
			return makeCategory(frame, name), {}
		end,
		RegisterCanvasLayoutSubcategory = function(parent, frame, name)
			frame.name = name
			frame.parent = parent and parent.name
			local cat = makeCategory(frame, name)
			cat.parent = parent
			if _G.InterfaceOptions_AddCategory then _G.InterfaceOptions_AddCategory(frame) end
			return cat, {}
		end,
		RegisterAddOnCategory = function(cat)
			if cat and cat.frame and not cat.parent and _G.InterfaceOptions_AddCategory then
				_G.InterfaceOptions_AddCategory(cat.frame)
			end
		end,
		OpenToCategory = function(id)
			local cat = categories[id]
			local open = _G.InterfaceOptionsFrame_OpenToCategory
			if cat and open then
				-- Called twice: the first call can land on the wrong page in older clients.
				open(cat.frame)
				open(cat.frame)
				return true
			end
			return false
		end,
	})
end

---------------------------------------------------------------------------
-- Tooltips: retail TooltipDataProcessor -> OnTooltipSet* hooks
---------------------------------------------------------------------------
S.TooltipDataType = (_G.Enum and _G.Enum.TooltipDataType) or { Item = 0, Spell = 1, Unit = 2 }

namespace("TooltipDataProcessor", {
	AddTooltipPostCall = function(dataType, callback)
		local T = S.TooltipDataType
		local tips = { _G.GameTooltip, _G.ItemRefTooltip, _G.ShoppingTooltip1, _G.ShoppingTooltip2 }
		local script, getData
		if dataType == T.Item then
			script = "OnTooltipSetItem"
			getData = function(tt)
				local name, link = tt:GetItem()
				local id = link and tonumber(link:match("item:(%d+)"))
				return { type = T.Item, id = id, hyperlink = link, name = name }
			end
		elseif dataType == T.Spell then
			script = "OnTooltipSetSpell"
			getData = function(tt)
				local name, id = tt:GetSpell()
				return { type = T.Spell, id = id, name = name }
			end
		elseif dataType == T.Unit then
			script = "OnTooltipSetUnit"
			getData = function(tt)
				local name, unit = tt:GetUnit()
				return { type = T.Unit, name = name, unit = unit, guid = unit and _G.UnitGUID(unit) }
			end
		else
			return
		end
		for _, tt in ipairs(tips) do
			if tt and tt.HookScript and tt:HasScript(script) then
				tt:HookScript(script, function(self) callback(self, getData(self)) end)
			end
		end
	end,
})

